// Bildschirme: Kopfzeile, Reiter und die Ansichten der Bereiche.
const POSO={TW:0,AB:1,MF:2,ST:3};
const SORTS={pos:(a,b)=>POSO[a.pos]-POSO[b.pos]||b.str-a.str,str:(a,b)=>b.str-a.str,age:(a,b)=>a.age-b.age,val:(a,b)=>value(b)-value(a)};
const SORTL={pos:'Position',str:'Stärke',age:'Alter',val:'Marktwert'};
const TABS=[['buero','Büro'],['kalender','Kalender'],['kader','Kader'],['kabine','Kabine'],['aufst','Aufstellung'],['tabelle','Tabelle'],['spielplan','Spielplan'],['pokal','Pokal'],['transfer','Transfers'],['finanzen','Finanzen'],['stadion','Stadion'],['training','Training & Jugend'],['stab','Stab']];
const fact=(k,v)=>`<div><span class="lbl">${k}</span><b>${v}</b></div>`;
const chip=id=>`<span class="dot" style="background:${S.teams[id].col}"></span>`;
const avgAtt=()=>S.att[1]?Math.round(S.att[0]/S.att[1]).toLocaleString('de-DE'):'–';
// Sperren je Wettbewerb (K09): „gesperrt (Liga 2, Pokal 1)“, mit Hinweis auf ein laufendes Verfahren
const sperrText=p=>{const l=sperreIn(p,'liga'),k=sperreIn(p,'pokal');if(!l&&!k)return'';const v=verfahrenVon(p);return`gesperrt (${[l?`Liga ${l}`:'',k?`Pokal ${k}`:''].filter(Boolean).join(', ')}${v?', Verfahren läuft':''})`;};
const ausfallText=p=>{if(p.inj>0){const i=verletzungInfo(p);return i?`${i.art==='krankheit'?'krank':'verletzt'} (${i.name}, noch ${spanneText(i.rest)}${gespritzt(p)?', gespritzt':''})`:`verletzt (${p.inj} ${p.inj===1?'Tag':'Tage'})`;}return sperrText(p);};
// Verletzte und Kranke (K10 §4): Art oder Verdacht, Ursache, Phase, Rückkehr als Spanne, fit spritzen am Spieltag, früher zurückholen aus dem Aufbautraining
function verletztenKarte(){const l=squad(S.my).filter(p=>p.inj>0).sort((a,b)=>a.inj-b.inj),b=verletzungsBilanz(S.my),spieltag=heuteMeinSpiel();
  const zeile=p=>{const i=verletzungInfo(p);if(!i)return`<tr><td>${esc(p.n)}</td><td colspan="4">${p.inj} Tage</td></tr>`;const d0=S.tag+i.rest[0],d1=S.tag+i.rest[1];
    const knopf=gespritzt(p)?'<span class="tag warn">gespritzt</span>':i.spritzbar&&spieltag?`<button onclick="event.stopPropagation();medSpritzen(${p.id})" title="Spielt heute mit Wirkung ×0,95. Danach mit ${Math.round(RMD.spritzen.verschlimmerung*100)} % schlimmer.">Fit spritzen</button>`:i.phase==='aufbau'&&!i.pflicht?`<button onclick="event.stopPropagation();medFrueher(${p.id})" title="Sofort einsatzfähig mit Frische ${RMD.frueher.frische} %, Rückfallrisiko doppelt">Früher zurückholen</button>`:'';
    return`<tr class="click" onclick="openP(${p.id})"><td><span class="pos ${p.pos}">${p.pos}</span> ${esc(p.n)}</td><td>${esc(i.name)}</td><td>${URSACHE[i.q]}</td><td>${PHASE[i.phase]}</td><td>${datumKurz(d0)}${d1>d0?' – '+datumKurz(d1):''}</td><td>${knopf}</td></tr>`;};
  return`<div class="card"><h3>Verletzte und Kranke</h3>${l.length?`<div class="tw"><table><thead><tr><th>Spieler</th><th>Diagnose</th><th>Ursache</th><th>Phase</th><th>Zurück etwa</th><th></th></tr></thead><tbody>${l.map(zeile).join('')}</tbody></table></div>`:'<p>Alle fit.</p>'}
    <p class="dim">Diese Saison: ${b.n} Verletzungen mit ${b.tage} Ausfalltagen (Ligaschnitt ${b.schnittN.toFixed(0)} mit ${b.schnittTage.toFixed(0)} Tagen), dazu ${b.krank} Krankheiten. Die erste Einschätzung ist grob, nach der Untersuchung (${diagnoseTage(S.my)} Tag${diagnoseTage(S.my)===1?'':'e'}) wird sie genauer. Ein guter Mannschaftsarzt macht beides schneller und genauer.</p></div>`;}
const gelbWarnung=p=>{const k=p.kt&&p.kt.liga;return k&&RD.gelbsperre.liga.includes(k+1)?`${k} Gelbe`:'';};
function status(p){if(p.inj>0||gesperrt(p))return`<span class="tag bad">${ausfallText(p)}</span>`;const sp=sperrText(p);if(sp)return`<span class="tag warn">${sp}</span>`;const g=gelbWarnung(p);if(g)return`<span class="tag warn" title="Bei der nächsten Gelben Karte ein Ligaspiel gesperrt">${g}</span>`;const w=wwTag(p);if(w)return w;if(p.list)return`<span class="tag offer">Transferliste</span>`;if(p.ct<=1)return`<span class="tag warn">Vertrag endet</span>`;return'';}
// Hauptknopf: Text und Zeile darunter
function knopf(){if(S.phase==='end')return['Saisonbilanz ▶','die Saison ist zu Ende'];if(S.fired)return['Jobangebote ▶','du wurdest entlassen'];
  if(heuteMeinSpiel())return['Tag beenden ▶','heute: '+spielName(meinSpiel(S.tag))];return['Tag beenden ▶','weiter bis '+datumKurz(naechsterHalt())];}
function hdr(){const t=myT(),tr=S.trust,[k1,k2]=knopf(),dt=datumVon(S.tag);return`<header class="top"><div class="club"><span class="chip" style="--c:${t.col}"></span><div><div class="cn">${esc(t.name)}</div><div class="sub">${esc(S.mgr)} · Saison ${S.season}/${(S.season+1)%100} · ${ligaName(t.lg)} · Platz ${rank(t.lg,S.my)}</div></div></div>
  <div class="kal" title="${datumLang(S.tag)}"><span>${WTL[dt.getUTCDay()]}</span><b>${dt.getUTCDate()}. ${MON[dt.getUTCMonth()]}</b><span>${dt.getUTCFullYear()}</span></div>
  <div class="stats"><div><span class="lbl">Kontostand</span><b class="${t.cash<0?'neg':''}">${fmt(t.cash)}</b></div><div title="Vertrauen des Vorstands ${Math.round(tr)} von 100"><span class="lbl">Vorstand</span>${rgMini(Math.round(tr),0,100,tr<30?'bad':tr<55?'warn':'good')}</div></div>
  <button class="go" onclick="tagBeenden()">${k1}<small>${k2}</small></button></header>`;}
let RENDERING=0,RERENDER=0;
function render(){if(RENDERING){RERENDER=1;return;}RENDERING=1;try{if(!S){renderStart();return;}
  app.innerHTML=`<div class="wrap">${hdr()}<nav class="tabs" aria-label="Bereiche">${TABS.map(([k,l])=>`<button class="${TAB===k?'on':''}" onclick="tab('${k}')">${l}</button>`).join('')}<button onclick="menu()">Menü</button></nav><main>${V[TAB]()}</main></div>`;}
  finally{RENDERING=0;if(RERENDER){RERENDER=0;setTimeout(render,0);}}}
const V={};
// Karte für ein Spiel deines Vereins (heute oder demnächst)
function spielKarte(e,heute){const f=paarung(e),wann=(heute?'Heute':datumKurz(e.tag))+(e.min!=null?', '+uhr(e.min)+' Uhr':'');
  if(!f)return`<div class="vs"><span>${wann} · ${spielName(e)}</span><b>Gegner wird ausgelost</b><span>K.-o.-Spiel mit Verlängerung und Elfmeterschießen</span></div>`;
  const home=f[0]===S.my,oid=home?f[1]:f[0],o=S.teams[oid],ort=e.art==='pokal'&&e.r===5?'Finale in Berlin':home?'Heimspiel':'Auswärtsspiel';
  if(!o)return`<div class="vs"><span>${wann} · ${spielName(e)} · ${ort}</span><b>${esc(tn(oid))}</b><span>Amateurverein · K.-o.-Spiel mit Verlängerung und Elfmeterschießen</span></div>`;
  if(e.art==='pokal'||e.art==='supercup')return`<div class="vs"><span>${wann} · ${spielName(e)} · ${ort}</span><b>${chip(o.id)}${esc(o.name)}</b><span>${o.lg}. Liga · Kaderstärke ${teamLevel(o.id).toFixed(1)} (deine: ${teamLevel(S.my).toFixed(1)}) · ${e.art==='supercup'?'bei Gleichstand direkt Elfmeterschießen':'K.-o.-Spiel'}</span></div>`;
  return`<div class="vs"><span>${wann} · ${spielName(e)} · ${home?'Heimspiel':'Auswärtsspiel'}</span><b>${chip(o.id)}${esc(o.name)}</b><span>Tabellenplatz ${rank(o.lg,o.id)} (${o.lg}. Liga) · Kaderstärke ${teamLevel(o.id).toFixed(1)} (deine: ${teamLevel(S.my).toFixed(1)})</span></div>`;}
// Termin eines Kalendertags aus Sicht deines Vereins, auch für vergangene Tage
function kalTermin(d){const r={kurz:'',cls:'',titel:''},l=meineLigaspiele().find(e=>e.tag===d);
  if(l){const f=S.fx[l.lg][l.md][l.i],home=f[0]===S.my,o=home?f[1]:f[0],x=S.res[l.lg].find(y=>y[4]===l.md&&y[0]===f[0]&&y[1]===f[1]);
    r.kurz=`${home?'H':'A'} ${S.teams[o].sh}`;r.titel=`${l.md+1}. Spieltag, ${uhr(l.min)} Uhr: ${home?'gegen':'bei'} ${S.teams[o].name}`;r.cls='sp';if(x){const gf=home?x[2]:x[3],ga=home?x[3]:x[2];r.erg=`${x[2]}:${x[3]}`;r.cls+=gf>ga?' win':gf<ga?' loss':' draw';}return r;}
  for(const e of termineAm(d)){
    if(e.art==='pokal'){const h=S.cup.hist[e.r],m=h&&h.find(y=>y[0]===S.my||y[1]===S.my);
      if(m){const home=m[0]===S.my,o=home?m[1]:m[0];r.kurz=`Pokal ${o>=1000?'Amat.':S.teams[o].sh}`;r.erg=`${m[2]}:${m[3]}${m[4]?' i.E.':''}`;r.cls='sp pk'+(winner({h:m[0],a:m[1],hg:m[2],ag:m[3],pen:m[4]})===S.my?' win':' loss');r.titel=`DFB-Pokal, ${POKAL_RUNDEN[e.r]}`;return r;}
      if(!h&&S.cup.alive.includes(S.my)){r.kurz='Pokal';r.cls='sp pk';r.titel=`DFB-Pokal, ${POKAL_RUNDEN[e.r]}`;return r;}
      r.kurz='Pokal';r.cls='fremd';r.titel=`DFB-Pokal, ${POKAL_RUNDEN[e.r]} (ohne dich)`;}
    if(e.art==='rel'||e.art==='rel2'){const x=S[e.art==='rel'?'relSp':'relSp2'][e.leg],mine=x?(x.h===S.my||x.a===S.my):(relBereit(e.art)&&relTeams(e.art).includes(S.my));
      if(mine){r.kurz='Relegation';r.cls='sp';r.titel=spielName(e);if(x)r.erg=`${x.hg}:${x.ag}`;return r;}if(!r.kurz){r.kurz='Relegation';r.cls='fremd';r.titel=spielName(e);}}
    if(e.art==='ende'){r.kurz='Saisonende';r.cls='ende';r.titel='Saisonende';return r;}}
  if(d===auftaktTag(myT())&&!r.kurz){r.kurz='Training';r.cls='ende';r.titel='Trainingsauftakt';}
  const ts=(S.testspiele||[]).find(x=>x.tag===d&&x.stand!=='abgesagt');if(ts&&!r.kurz){r.kurz=`Test ${ts.gegner>=1000?'Amat.':S.teams[ts.gegner].sh}`;r.cls='sp test';r.titel=`Testspiel ${ts.heim?'gegen':'bei'} ${tn(ts.gegner)}${ts.stand==='angefragt'?' (angefragt)':''}`;if(ts.erg)r.erg=`${ts.heim?ts.erg.hg:ts.erg.hg}:${ts.erg.ag}`;}
  const la=lagerAktiv(d);if(la&&!r.kurz){r.kurz='Lager';r.cls='ende';r.titel=`Trainingslager ${RLA.orte[la.ort].name}`;}
  return r;}
function wochenLeiste(){let h='';for(let d=S.tag;d<S.tag+7;d++){const dt=datumVon(d),k=kalTermin(d),u=S.phase==='sommer'||d<auftaktTag(myT()),p=u?{name:d>=tageDerSaison()?'Neue Saison':'Urlaub'}:pauseAm(d,myT().lg);
    h+=`<div class="wt ${d===S.tag?'heute':''} ${p&&!k.kurz?'pause':''} ${k.cls}" title="${esc(datumLang(d)+(k.titel?': '+k.titel:p?': '+p.name:''))}"><span>${WT[dt.getUTCDay()]}</span><b>${dt.getUTCDate()}.${dt.getUTCMonth()+1}.</b><i>${esc(k.kurz||(p?p.name.replace('Länderspielpause','Länderspiele'):''))}</i></div>`;}
  return`<div class="woche" aria-label="Die nächsten 7 Tage">${h}</div>`;}
// Sportgericht (K09 §4.1): Anträge mit Frist (annehmen oder Einspruch), laufende Einsprüche, letzte Urteile gegen eigene Spieler
function sportgerichtKarte(){const V=meineVerfahren(),A=(S.sgArchiv||[]).filter(u=>u.team===S.my).slice(0,3);if(!V.length&&!A.length)return'';const E=RD.einspruch;
  const zeile=v=>{const p=PIX.get(v.pid),kopf=`<b>${esc(p.n)}</b> · ${VERGEHEN[v.art]} am ${datumKurz(v.tag)} (${WB_NAME[v.wb]})`;
    if(v.stand==='offen')return`<p>${kopf}: vorläufig gesperrt, der Antrag kommt bis ${datumKurz(v.antragAm)}.</p>`;
    if(v.stand==='einspruch')return`<p>${kopf}: Einspruch gegen ${v.antrag} Spiel${v.antrag===1?'':'e'} läuft, Urteil am ${datumKurz(v.urteilAm)}. Bis dahin bleibt er gesperrt.</p>`;
    const rest=v.frist-S.tag;return`<div class="row between" style="padding:6px 0;border-bottom:1px solid var(--rule)"><span>${kopf}: Antrag <b>${v.antrag} Spiel${v.antrag===1?'':'e'}</b>${v.vor?` (Wiederholungstäter)`:''} <span class="tag ${rest<=0?'warn':''}">${rest<=0?'Frist endet heute':'Frist bis '+datumKurz(v.frist)}</span></span>
      <span class="row"><button onclick="sgAnnehmen(${v.id})">Strafe annehmen</button><button onclick="sgEinspruch(${v.id})" ${v.antrag<2?'disabled title="Weniger als ein Spiel geht nicht"':`title="Anwalt ${fmt(E.kosten[0])} bis ${fmt(E.kosten[1])}. Meist bestätigt, manchmal ein Spiel weniger, selten eins mehr."`}>Einspruch</button></span></div>`;};
  return`<div class="card"><h3>Sportgericht</h3>${V.map(zeile).join('')}${A.length?`<p class="dim" style="margin-top:8px">Zuletzt: ${A.map(u=>`${esc(u.n)} ${u.urteil} Spiel${u.urteil===1?'':'e'} (${AUSGANG[u.ausgang]})`).join(' · ')}</p>`:''}<p class="dim">Ohne Antwort bis zur Frist gilt der Antrag als angenommen.</p></div>`;}
// Pokal-Auslosung (K13 §3.2): am Tag der Auslosung alle Paarungen, dein Los hervorgehoben
function pokalLosKarte(){const L=S.cup&&S.cup.los;if(!L||L.am!==S.tag||S.phase!=='play')return'';
  return`<div class="card"><h3>Auslosung DFB-Pokal, ${POKAL_RUNDEN[L.r]}</h3><p class="dim">Gespielt am ${datumKurz(S.plan.pokal[L.r][0])}.${L.r===0?' Die Amateure aus Topf 2 haben Heimrecht.':L.r<=RWB.pokal.heimrechtBisRunde?' Amateure (3. Liga und darunter) haben gegen Profis Heimrecht.':''}</p>
    <div class="tw"><table><tbody>${L.paare.map(([h,a])=>{const m=h===S.my||a===S.my;return`<tr${m?' class="me"':''}><td>${m?'<b>':''}${esc(tn(h))}${m?'</b>':''}</td><td>–</td><td>${m?'<b>':''}${esc(tn(a))}${m?'</b>':''}</td></tr>`;}).join('')}</tbody></table></div></div>`;}
V.buero=()=>{const t=myT(),d=S.tag;let heute='';
  if(S.fired)heute=`<p><b>Du wurdest entlassen.</b> Oben auf „Jobangebote“ klicken.</p>`;
  else if(S.phase==='end')heute=`<p>Die Saison ist vorbei. Oben geht es zur Saisonbilanz.</p>`;
  else if(heuteMeinSpiel())heute=spielKarte(meinSpiel(d),true)+`<p class="dim" style="margin-top:8px">„Tag beenden“ führt zum Vorbericht und zum Anpfiff.</p>`;
  else if(S.phase==='sommer')heute=`<p><b>${esc(tagesText(d))}</b></p><p class="dim">Am ${datumMittel(tageDerSaison())} beginnt die neue Saison: Spielplan, Verträge, Sponsorangebote. Danach Trainingsauftakt und Vorbereitung.</p>`;
  else{const n=naechstesSpiel(d+1);heute=`<p><b>${esc(tagesText(d))}</b></p>${n?spielKarte(n,false):'<p class="dim">Keine Spiele mehr in dieser Saison.</p>'}`;}
  const warn=[];const sq=squad(S.my);
  if(sq.length<18)warn.push(`Nur ${sq.length} Spieler im Kader – verpflichte Verstärkung.`);
  const out=sq.filter(p=>!avail(p));if(out.length)warn.push(`Nicht einsatzbereit: ${out.map(p=>`${esc(p.n)} (${ausfallText(p)})`).join(', ')}.`);
  const exp=sq.filter(p=>p.ct<=1);if(exp.length&&meineSpieltage()>=RK.hinweisVertraegeAbSpieltag)warn.push(`Verträge enden zum Saisonende: ${exp.map(p=>esc(p.n)).join(', ')}.`);
  if(t.cash<0)warn.push('Das Konto ist im Minus. Der Vorstand verliert Vertrauen – Kredit aufnehmen oder Spieler verkaufen.');
  const sp=S.sponsOffers?`<div class="card"><h3>Trikotsponsor wählen</h3><div class="opts">${S.sponsOffers.map((o,i)=>`<button class="opt" onclick="pickSponsor(${i})"><b>${esc(o.name)}</b><span>${fmt(o.base)} pro Spieltag${o.win?` + ${fmt(o.win)} pro Sieg`:''} · ${o.info}</span></button>`).join('')}</div></div>`:'';
  const of=S.offers.length?`<div class="card"><h3>Angebote für deine Spieler</h3>${S.offers.map((o,i)=>{const p=PIX.get(o.pid),rest=o.bis-S.tag;return`<div class="row between" style="padding:6px 0;border-bottom:1px solid var(--rule)"><span><b>${esc(S.teams[o.tid].name)}</b> bietet ${fmt(o.amt)} für ${esc(p.n)} (Marktwert ${fmt(value(p))}) <span class="tag ${rest<=1?'warn':''}">gilt ${rest<=0?'nur noch heute':'bis '+datumKurz(o.bis)}</span></span><span class="row"><button onclick="acceptOffer(${i})">Annehmen</button><button onclick="declineOffer(${i})">Ablehnen</button></span></div>`;}).join('')}</div>`:'';
  let lm='';const m=LAST&&LAST.mine;if(m&&m.grades){const g=Object.entries(m.grades).map(([id,gr])=>[PIX.get(+id),gr]).filter(x=>x[0]).sort((a,b)=>a[1]-b[1]);
    lm=`<div class="card"><h3>Letztes Spiel: ${esc(tn(m.h))} – ${esc(tn(m.a))} ${m.hg}:${m.ag}</h3>${m.att?`<p class="dim">${m.att.toLocaleString('de-DE')} Zuschauer</p>`:''}<div class="tw"><table><tbody>${g.map(([p,gr])=>`<tr class="click" onclick="openP(${p.id})"><td><span class="pos ${p.pos}">${p.pos}</span></td><td>${esc(p.n)}</td><td class="num"><b>Note ${gr.toFixed(1).replace('.',',')}</b></td></tr>`).join('')}</tbody></table></div></div>`;}
  return`<div class="grid">
    <div class="card"><h2>Heute · ${datumLang(d)}</h2>${heute}${S.phase!=='end'?wochenLeiste():''}</div>
    <div class="card"><h2>Saisonziel</h2><p>${targetText(t.lg,S.target)}</p><p class="dim">Aktuell Platz ${rank(t.lg,S.my)}</p><div class="rgs" style="margin:10px 0">${rgAnzeige({label:'Vorstand',sub:'Vertrauen 0–100',min:0,max:100,wert:Math.round(S.trust),zonen:RU.zonenVertrauen})}</div><p class="dim">Sponsor: ${S.spons?esc(S.spons.name):'noch keiner'} · Training: ${(RT.vorlagen[myT().vorlage]||{name:'Co-Trainer entscheidet'}).name}</p></div>
    ${gespraechswunschKarte()}${sp}${of}${pokalLosKarte()}${sportgerichtKarte()}${warn.length?`<div class="card"><h3>Hinweise</h3>${warn.map(x=>`<p>${x}</p>`).join('')}</div>`:''}${lm}
    <div class="card"><h2>Nachrichten</h2><div class="news">${S.news.map(n=>`<div class="${n.c}"><small>${n.w}</small>${esc(n.t)}</div>`).join('')}</div></div></div>`;};
V.kader=()=>{const sq=squad(S.my).sort(SORTS[SORT]),xi=new Set(myXI()),pay=sq.reduce((s,p)=>s+p.sal,0);
  return`<div class="card"><div class="row between"><h2>Kader (${sq.length} Spieler)</h2><label>Sortieren <select id="sortsel" onchange="SORT=this.value;render()">${Object.keys(SORTS).map(k=>`<option value="${k}" ${k===SORT?'selected':''}>${SORTL[k]}</option>`).join('')}</select></label></div>
  <div class="tw"><table><thead><tr><th>Pos</th><th>Name</th><th class="num">Alter</th><th>Stärke</th><th>Form</th><th>Frische</th><th>Stimmung</th><th>Status</th><th class="num">Tore</th><th class="num">Vertrag</th><th class="num">Gehalt</th><th class="num">Marktwert</th></tr></thead><tbody>
  ${sq.map(p=>`<tr class="click" onclick="openP(${p.id})"><td><span class="pos ${p.pos}">${p.pos}</span></td><td>${xi.has(p.id)?`<b>${esc(p.n)}</b>`:esc(p.n)}</td><td class="num">${p.age}</td><td>${rgMini(Math.round(p.str),1,99)}</td><td>${rgMini(p.form,0,20,'',1)}</td><td>${rgMini(Math.round(p.fit),0,100,fitArt(p.fit))}</td><td>${rgMini(Math.round(stimmung(p)),0,100,stimmungArt(p))}</td><td>${status(p)}</td><td class="num">${p.g}</td><td class="num">${S.season+p.ct}</td><td class="num">${fmt(p.sal)}</td><td class="num">${fmt(value(p))}</td></tr>`).join('')}</tbody></table></div>
  <p class="dim">Fett = aktuelle Startelf · Stärke 1–99, Form 0–20 (Mitte 10), Frische 0–100 %, Stimmung 0–100 (Gründe in der Kabine) · Gehaltssumme ${fmt(pay)} pro Saison · Klick auf einen Spieler: Werte, Vertrag, Transferliste.${S.season===2026&&KADER_STAND[myT().sh]?` · Kaderdaten: Wikipedia, Stand ${KADER_STAND[myT().sh]}`:''}</p></div>${verletztenKarte()}`;};
// Wechselwunsch als Hinweis (K14 §5.4): bei dir ab Stufe 2, bei fremden Spielern nur der offizielle (andere Vereine wissen es)
function wwTag(p){const w=p.ww||0;if(p.team===S.my){if(w>=3)return`<span class="tag bad" title="${esc(WW_NAME[w])}">will weg</span>`;if(w===2)return`<span class="tag warn" title="Gesprächswunsch">will reden</span>`;return'';}return w>=3?'<span class="tag warn">will weg</span>':'';}
const stimmungArt=p=>{const s=stimmung(p);return s<RKA.wechsel.gespraech[0]?'bad':s<RKA.wechsel.grummeln[0]?'warn':'';};
// Gesprächswünsche im Büro (K14 §4.3)
function gespraechswunschKarte(){const l=(S.gw||[]).map(g=>PIX.get(g.pid)).filter(p=>p&&p.team===S.my);if(!l.length)return'';
  return`<div class="card"><h3>Gesprächswunsch</h3>${l.map(p=>`<div class="row between" style="padding:6px 0;border-bottom:1px solid var(--rule)"><span><b>${esc(p.n)}</b> möchte mit dir sprechen (Stimmung ${Math.round(p.st)}, ${esc(BAUSTEIN_GRUND[hauptgrund(p)]||'unzufrieden')}).</span><button onclick="openP(${p.id})">Zum Gespräch</button></div>`).join('')}<p class="dim">Ohne Gespräch und ohne Besserung will er nach vier Wochen offiziell weg. Gespräche diese Woche: ${gespraecheDieseWoche()} von ${RGS.proWoche}.</p></div>`;}
// Stimmung und Gespräch auf der Spielerkarte (K14, K15)
function stimmungKarte(p){const B=bausteine(p),z=zielStimmung(p),e=erwartungEinsatz(p),f=freundeVon(p),r=rivalen(p),vs=(S.vs||[]).filter(v=>v.pid===p.id&&v.stand==='offen'),frei=gespraecheFrei();
  const teile=Object.entries(B).filter(([,v])=>Math.abs(v)>=0.5).map(([k,v])=>`${BAUSTEIN_NAME[k]} ${v>0?'+':'−'}${de(Math.abs(v))}`).join(' · ')||'alles im Gleichgewicht';
  const anlass=Object.keys(THEMEN).map(k=>[k,themaAnlass(p,k)]);
  return`<div class="card"><h3>Stimmung und Gespräch</h3><div class="rgs">${rgAnzeige({label:'Stimmung',sub:`0–100, bewegt sich langsam zum Ziel ${Math.round(z)}`,min:0,max:100,wert:Math.round(stimmung(p)),zonen:RU.zonenStimmung,marker:[{v:Math.round(z),t:'Ziel'}]})}</div>
    <p class="dim">Gründe: ${teile}</p>
    <div class="facts">${fact('Wechselwunsch',esc(WW_NAME[p.ww||0]))}${fact('Einsatzzeit',`${Math.round((p.ea==null?e:p.ea)*100)} % (erwartet ${Math.round(e*100)} %)`)}${fact('Sieht sich als',esc(KR_NAME[KR_AUS_STUFE[einschaetzung(p)]]))}</div>
    <label>Kaderrolle <select id="krsel" onchange="setKaderrolle(${p.id},this.value)"><option value="">Co-Trainer: ${esc(KR_NAME[p.krA||'ergaenzung'])}</option>${KR_LISTE.map(k=>`<option value="${k}" ${p.kr===k?'selected':''}>${KR_NAME[k]}</option>`).join('')}</select></label>
    ${f.length||r.length?`<p class="dim">${f.length?'Freunde: '+f.map(q=>esc(q.n)).join(', '):''}${f.length&&r.length?' · ':''}${r.length?'Rivale um den Platz: '+r.map(q=>esc(q.n)).join(', '):''}</p>`:''}
    ${vs.length?`<p><b>Zusagen:</b> ${vs.map(v=>esc(versprechenText(v))).join('; ')}</p>`:''}
    <div class="form"><label>Thema <select id="gthema">${anlass.map(([k,a])=>`<option value="${k}" title="${esc(THEMA_HILFE[k])}">${THEMEN[k]}${a?' (kein Anlass)':''}</option>`).join('')}</select></label>
    <label>Haltung <select id="ghaltung">${Object.entries(HALTUNGEN).map(([k,l])=>`<option value="${k}" ${k==='s'?'selected':''}>${l}</option>`).join('')}</select></label>
    <button onclick="gespraechUI(${p.id})" ${frei?'':'disabled'}>Gespräch führen</button></div>
    <p class="dim">Gespräche diese Woche: ${RGS.proWoche-frei} von ${RGS.proWoche} · Glaubwürdigkeit ${Math.round(glaub())} · Zusagen musst du halten, sonst leidet die Glaubwürdigkeit.</p><p id="gmsg" class="msg" aria-live="polite"></p></div>`;}
const fitArt=f=>{const z=RU.zonenFitness.find(q=>f>=q.von&&f<=q.bis);return z&&z.art!=='good'?z.art:'';};
// Tauziehen gegen den Gegner deines nächsten Spiels (nur wenn er feststeht)
function tauziehenNaechstes(){const e=heuteMeinSpiel()?meinSpiel(S.tag):naechstesSpiel(S.tag+1),f=e&&paarung(e);if(!f)return'';
  const home=f[0]===S.my,o=home?f[1]:f[0],me=side(S.my,home,false),op=side(o,!home,false);
  return`<h3 style="margin-top:14px">Vergleich mit ${esc(tn(o))}</h3><p class="dim">${esc(spielName(e))}, ${datumKurz(e.tag)}, ${home?'zu Hause':'auswärts'} (mit Heimvorteil)</p>${rgTauziehen('Dein Verein',tn(o),[['Dein Angriff gegen ihre Abwehr',+me.A.toFixed(1),+op.D.toFixed(1)],['Deine Abwehr gegen ihren Angriff',+me.D.toFixed(1),+op.A.toFixed(1)]])}`;}
V.aufst=()=>{const t=myT(),sl=slotsVerein(t),xi=myXI();const sq=squad(S.my).sort(SORTS.pos),sd=side(S.my,false,true),stil=STILE.includes(t.stil)?t.stil:'ausgewogen';
  const row=pos=>`<div class="prow">${sl.map((s,i)=>posGruppe(s)===pos?i:-1).filter(i=>i>=0).map(i=>{const p=PIX.get(xi[i]);return`<div class="tok"><b>${p?Math.round(p.str):'–'}</b><span>${p?esc(last(p.n)):'frei'}</span></div>`;}).join('')}</div>`;
  return`<div class="grid"><div class="card"><h2>Aufstellung ${t.form}</h2><div class="pitch">${row('ST')}${row('MF')}${row('AB')}${row('TW')}</div><p class="dim" style="margin-top:8px">Angriffswert ${sd.A.toFixed(1)} · Abwehrwert ${sd.D.toFixed(1)} (ohne Heimvorteil)</p>${tauziehenNaechstes()}</div>
  <div class="card"><h3>Taktik</h3><div class="form"><label>System <select id="formsel" onchange="setForm(this.value)">${Object.keys(RE.formationen).map(f=>`<option ${f===t.form?'selected':''}>${f}</option>`).join('')}</select></label>
  <label>Ausrichtung <select id="tacsel" onchange="setTac(this.value)">${Object.entries(AUSRICHTUNG).map(([k,l])=>`<option value="${k}" ${k===t.tac?'selected':''}>${l}</option>`).join('')}</select></label>
  <label>Einsatz <select id="einsel" onchange="setEin(this.value)">${Object.entries(EINSATZ).map(([k,l])=>`<option value="${k}" ${k===t.ein?'selected':''}>${l}</option>`).join('')}</select></label>
  <label>Spielstil <select id="stilsel" onchange="setStil(this.value)">${STILE.map(k=>`<option value="${k}" ${k===stil?'selected':''}>${STIL_NAME[k]}</option>`).join('')}</select></label>
  <label>Einstellung zum nächsten Spiel <select id="einstsel" onchange="setEinstellung(this.value)">${Object.entries(EINSTELLUNG_NAME).map(([k,l])=>`<option value="${k}" ${k===(t.einstellung||'normal')?'selected':''}>${l}</option>`).join('')}</select></label>
  <button onclick="autoXI()">Beste Elf automatisch aufstellen</button></div>
  ${taktikInfo(t,sd,stil)}<hr>
  <h3>Startelf</h3><div class="slots">${sl.map((pos,i)=>`<label class="slot ${rolleWaehlbar(slots(t.form)[i])?'rolle':''}"><span class="pos ${posGruppe(pos)}">${pos}</span>${rolleWahl(t,i)}<select id="slot${i}" onchange="setSlot(${i},this.value)">${xi[i]==null?'<option>– niemand verfügbar –</option>':''}${sq.map(p=>`<option value="${p.id}" ${xi[i]===p.id?'selected':''} ${avail(p)?'':'disabled'}>${esc(p.n)} · ${p.fp||p.pos} · ${Math.round(eff(p,pos)*10)/10} · ${Math.round(p.fit)}%${p.inj>0?' · verletzt':p.sus>0?' · gesperrt':''}</option>`).join('')}</select></label>`).join('')}</div>
  <p class="dim" style="margin-top:8px">Offensiv: mehr Tore, mehr Gegentore. Hart: etwas stärker, aber mehr Karten und Verletzungen. Spieler auf fremder Position verlieren deutlich an Stärke. Rollen im Mittelfeld und Sturm (DM, ZM, SM, OM, MS, HS) wählst du links am Platz, höchstens ein Spielmacher.</p>
  ${schuetzenKarte(t,xi)}</div></div>`;};
// Umsetzung, Vertrautheit und Kreislauf (K06 §5.2–5.4)
function taktikInfo(t,sd,stil){const u=stil==='ausgewogen'?1:umsetzung(sd,stil),vs=vertraut(t,'stil',stil),vo=vertraut(t,'ordnung',t.form),K=RTA.kreislauf,schlaegt=K[stil],verliert=Object.keys(K).find(k=>K[k]===stil);
  return`<div class="rgs">${rgAnzeige({label:'Umsetzung',sub:stil==='ausgewogen'?'ausgewogen braucht keine Umsetzung':'Voraussetzungen im Kader und Vertrautheit. Vorteile wirken nur zu diesem Anteil, Nachteile immer voll.',min:0,max:100,wert:Math.round(u*100),einheit:' %',zonen:[{von:0,bis:40,art:'bad',text:'kaum umsetzbar: nur die Nachteile wirken'},{von:40,bis:70,art:'warn',text:'halbherzig'},{von:70,bis:100,art:'good',text:'passt zum Kader'}]})}
    ${rgAnzeige({label:'Vertrautheit Spielstil',sub:'+5 pro Trainingswoche, +3 je Spiel, ungenutzt −2',min:0,max:100,wert:Math.round(vs)})}
    ${rgAnzeige({label:'Vertrautheit Grundordnung',sub:vo<RTA.vertrautheit.ordnungUnter?`unter ${RTA.vertrautheit.ordnungUnter}: Teamwerte bis zu 3 % schwächer`:'eingespielt',min:0,max:100,wert:Math.round(vo)})}</div>
    <p class="dim">${esc(STIL_TEXT[stil])}${schlaegt?` <b>Schlägt</b> ${STIL_NAME[schlaegt]}, <b>verliert gegen</b> ${STIL_NAME[verliert]}.`:''}${(t.einstellung||'normal')==='saison'?' „Spiel der Saison“: heute 4 % stärker, danach zehn Tage Kater.':(t.einstellung==='locker')?' „Locker angehen“: 4 % schwächer, aber weniger müde.':''}</p>`;}
// Rolle eines Platzes wählen (K06 §3.1)
function rolleWahl(t,i){const grund=slots(t.form)[i],g=rolleWaehlbar(grund);if(!g)return'';const akt=slotsVerein(t)[i];
  return`<select class="rollesel" aria-label="Rolle auf Platz ${i+1}" onchange="setRolle(${i},this.value)">${RTA.rollen[g].map(r=>`<option ${r===akt?'selected':''}>${r}</option>`).join('')}</select>`;}
// Standardschützen (K06 §5.8): ohne Wahl schießt der Beste nach Merkmal und Stärke
function schuetzenKarte(t,xi){const el=xi.map(id=>PIX.get(id)).filter(Boolean),sch=t.schuetzen||{},opt=(sel)=>`<option value="">automatisch</option>${el.map(p=>`<option value="${p.id}" ${p.id===sel?'selected':''}>${esc(p.n)}${hatMk(p,'elfmeter')?' (Elfmeter)':''}${hatMk(p,'freistoss')?' (Freistoß)':''}${hatMk(p,'flankengeber')?' (Flanken)':''}</option>`).join('')}`;
  const elf=sch.elfmeter||[];
  return`<hr><h3>Standardschützen</h3><div class="form schuetzen">
    ${[0,1,2,3,4].map(i=>`<label>Elfmeter ${i+1} <select onchange="setSchuetze('elfmeter',${i},this.value)">${opt(elf[i])}</select></label>`).join('')}
    <label>Direkte Freistöße <select onchange="setSchuetze('freistoss',0,this.value)">${opt(sch.freistoss)}</select></label>
    <label>Ecken <select onchange="setSchuetze('ecke',0,this.value)">${opt(sch.ecke)}</select></label></div>
    <p class="dim">Wer Standards schießt, sammelt dort Erfahrung (Lernen im Spiel). Fällt ein Schütze aus, übernimmt der nächste der Liste, sonst der Beste auf dem Platz.</p>`;}
V.tabelle=()=>{const lg=TLG||myT().lg,tb=table(lg),ts=topScorers(lg),reihe=lg===3?aufstiegsReihe3():[];
  const z=(i,id)=>lg===1?(i<4?'z1':i<6?'z2':i===15?'z3':i>=16?'z4':''):lg===2?(i<2?'z1':i===2||i===15?'z3':i>=16?'z4':''):(id===reihe[0]||id===reihe[1]?'z1':id===reihe[2]?'z3':i>=tb.length-RS.abstieg3?'z4':'');
  const leg=lg===1?'Grün: Champions League · Blau: Europa League · Gelb: Relegation · Rot: Abstieg':lg===2?'Grün: Aufstieg · Gelb: Relegation (Platz 3 gegen den 16. der 1. Liga, Platz 16 gegen den 3. der 3. Liga) · Rot: Abstieg':'Grün: Aufstieg · Gelb: Relegation gegen den 16. der 2. Liga · Rot: Abstieg in die Regionalliga · (II) = Zweitmannschaft, darf nicht aufsteigen';
  return`<div class="grid wide"><div class="card"><div class="row between"><h2>${ligaName(lg)}</h2><div class="row">${LIGEN.map(l=>`<button class="${l===lg?'go':''}" onclick="TLG=${l};render()">${l}. Liga</button>`).join('')}</div></div>
  <div class="tw"><table><thead><tr><th class="num">#</th><th>Verein</th><th class="num">Sp</th><th class="num">S</th><th class="num">U</th><th class="num">N</th><th class="num">Tore</th><th class="num">Diff</th><th class="num">Pkt</th></tr></thead><tbody>
  ${tb.map((r,i)=>`<tr class="${r.id===S.my?'me':''}"><td class="num ${z(i,r.id)}">${i+1}</td><td>${chip(r.id)}${esc(S.teams[r.id].name)}${S.teams[r.id].zweite>=0?' <span class="dim">(II)</span>':''}</td><td class="num">${r.sp}</td><td class="num">${r.s}</td><td class="num">${r.u}</td><td class="num">${r.n}</td><td class="num">${r.tf}:${r.ta}</td><td class="num">${r.tf-r.ta}</td><td class="num"><b>${r.p}</b></td></tr>`).join('')}</tbody></table></div>
  <p class="dim">${leg}</p></div>
  <div class="card"><h3>Torjäger</h3>${ts.length?`<table><tbody>${ts.map((p,i)=>`<tr class="click ${p.team===S.my?'me':''}" onclick="openP(${p.id})"><td class="num">${i+1}.</td><td>${esc(p.n)}<br><span class="dim">${esc(S.teams[p.team].name)}</span></td><td class="num"><b>${p.g}</b></td></tr>`).join('')}</tbody></table>`:'<p class="dim">Noch keine Tore.</p>'}</div></div>`;};
V.spielplan=()=>{const t=myT(),lg=t.lg,Z=S.plan.zeit[lg],lastMd=S.res[lg].reduce((a,r)=>Math.max(a,r[4]),0),md=TDAY!=null&&TDAY<S.fx[lg].length?TDAY:lastMd;
  const rows=meineLigaspiele().map(e=>{const f=S.fx[lg][e.md][e.i],home=f[0]===S.my,o=home?f[1]:f[0],r=S.res[lg].find(x=>x[4]===e.md&&x[0]===f[0]&&x[1]===f[1]);let cls='';if(r){const gf=home?r[2]:r[3],ga=home?r[3]:r[2];cls=gf>ga?'win':gf<ga?'loss':'draw';}
    return`<tr class="${e.tag===S.tag?'me':''}"><td class="num">${e.md+1}.</td><td>${datumKurz(e.tag)} ${uhr(e.min)}</td><td>${home?'Heim':'Ausw.'}</td><td>${chip(o)}${esc(S.teams[o].name)}</td><td class="num"><span class="res ${cls}">${r?r[2]+':'+r[3]:'–'}</span></td></tr>`;}).join('');
  const day=S.fx[lg][md].map(([h,a],i)=>({h,a,z:Z[md][i]})).sort((x,y)=>x.z[0]-y.z[0]||x.z[1]-y.z[1]).map(({h,a,z})=>{const r=S.res[lg].find(x=>x[4]===md&&x[0]===h&&x[1]===a);return`<tr class="${h===S.my||a===S.my?'me':''}"><td class="dim">${datumKurz(z[0])} ${uhr(z[1])}</td><td>${esc(S.teams[h].name)}</td><td class="num"><b>${r?r[2]+':'+r[3]:'–:–'}</b></td><td>${esc(S.teams[a].name)}</td></tr>`;}).join('');
  return`<div class="grid"><div class="card"><h2>Spielplan ${ligaName(lg)}</h2><div class="tw"><table><tbody>${rows}</tbody></table></div><p class="dim">${S.season===2026?'Offizieller Spielplan 2026/27. Wo DFL und DFB noch keine Anstoßzeit festgelegt haben, verteilt das Spiel die Partien nach dem üblichen Raster.':'Spielplan ausgelost, Anstoßzeiten nach dem üblichen Raster.'}</p></div>
  <div class="card"><div class="row between"><h3>Spieltag ansehen</h3><select id="daysel" onchange="TDAY=+this.value;render()">${S.fx[lg].map((_,i)=>`<option value="${i}" ${i===md?'selected':''}>${i+1}. Spieltag · ${datumKurz(Math.min(...Z[i].map(z=>z[0])))}</option>`).join('')}</select></div><div class="tw"><table><tbody>${day}</tbody></table></div></div></div>`;};
// Kalender: Monatsansicht mit deinen Spielen, Pokal, Pausen. KMON = Verschiebung in Monaten gegenüber heute.
let KMON=0;
V.kalender=()=>{const h=datumVon(S.tag),y=h.getUTCFullYear(),m=h.getUTCMonth()+KMON,erster=new Date(Date.UTC(y,m,1)),jahr=erster.getUTCFullYear(),mon=erster.getUTCMonth(),
    tage=new Date(Date.UTC(jahr,mon+1,0)).getUTCDate(),vorne=(erster.getUTCDay()+6)%7,iso=n=>`${jahr}-${String(mon+1).padStart(2,'0')}-${String(n).padStart(2,'0')}`;
  let c='';for(let i=0;i<vorne;i++)c+='<div class="kt leer"></div>';
  for(let n=1;n<=tage;n++){const d=tagAusDatum(iso(n),S.season),inS=d>=0&&d<=365,k=inS?kalTermin(d):{},p=inS?pauseAm(d,myT().lg):null;
    c+=`<div class="kt ${d===S.tag?'heute':''} ${d<S.tag?'vorbei':''} ${p&&!k.kurz?'pause':''} ${k.cls||''}" title="${esc((inS?datumLang(d):'')+(k.titel?': '+k.titel:p?': '+p.name:''))}"><span>${n}</span>${k.kurz?`<i>${esc(k.kurz)}</i>`:p?`<i class="dim">${esc(p.name.replace('Länderspielpause','Länderspiele'))}</i>`:''}${k.erg?`<b>${k.erg}</b>`:''}</div>`;}
  const komm=[];for(let d=S.tag;d<=S.plan.ende&&komm.length<6;d++){const e=meinSpiel(d)||termineAm(d).find(x=>x.art==='ende');if(e&&!(d===S.tag&&S.gespielt===d))komm.push([d,e]);}
  return`<div class="grid wide"><div class="card"><div class="row between"><h2>${MONL[mon]} ${jahr}</h2><div class="row"><button onclick="KMON--;render()" aria-label="Monat zurück">◀</button><button onclick="KMON=0;render()">Heute</button><button onclick="KMON++;render()" aria-label="Monat vor">▶</button></div></div>
  <div class="kgrid">${['Mo','Di','Mi','Do','Fr','Sa','So'].map(x=>`<div class="kh">${x}</div>`).join('')}${c}</div>
  <p class="dim" style="margin-top:8px">H = Heimspiel, A = Auswärtsspiel, dazu das Kürzel des Gegners. Gestrichelt: Länderspiel- oder Winterpause. Termine 2026/27 nach dem Rahmenterminkalender, einzelne Spieltage geschätzt.</p></div>
  <div class="card"><h3>Nächste Termine</h3>${komm.length?`<table><tbody>${komm.map(([d,e])=>{const f=e.art==='ende'?null:paarung(e),o=f?(f[0]===S.my?f[1]:f[0]):null;return`<tr><td>${datumKurz(d)}</td><td>${esc(spielName(e))}${f?`<br><span class="dim">${f[0]===S.my?'gegen':'bei'} ${esc(tn(o))}</span>`:e.art==='pokal'?'<br><span class="dim">Gegner wird ausgelost</span>':''}</td></tr>`;}).join('')}</tbody></table>`:'<p class="dim">Keine Termine mehr.</p>'}</div></div>`;};
V.pokal=()=>{const done=S.cup.hist.length>=6,alive=S.cup.alive.includes(S.my);
  return`<div class="card"><h2>DFB-Pokal ${S.season}/${(S.season+1)%100}</h2><p>${done?`Pokalsieger: <b>${esc(tn(S.cup.alive[0]))}</b>`:alive?'Dein Verein ist noch im Wettbewerb.':'Dein Verein ist ausgeschieden.'} <span class="dim">64 Teams: 36 aus der 1. und 2. Liga, ${RF.pokal.drittligisten} aus der 3. Liga und ${RF.pokal.amateure} Amateurklubs. K.-o.-Modus mit Verlängerung und Elfmeterschießen.</span></p>
  <p class="dim">Termine: ${POKAL_RUNDEN.map((n,i)=>`${n} ${datumKurz(S.plan.pokal[i][0])}`).join(' · ')}</p>
  ${S.cup.hist.map((rd,i)=>`<h3 style="margin-top:14px">${POKAL_RUNDEN[i]} · ${datumKurz(S.plan.pokal[i][0])}</h3><div class="tw"><table><tbody>${rd.map(([h,a,hg,ag,pen])=>`<tr class="${h===S.my||a===S.my?'me':''}"><td>${esc(tn(h))}</td><td class="num"><b>${hg}:${ag}</b>${pen?` <span class="dim">(${pen[0]}:${pen[1]} i.E.)</span>`:''}</td><td>${esc(tn(a))}</td></tr>`).join('')}</tbody></table></div>`).reverse().join('')||`<p class="dim">Die 1. Runde wird am ${datumMittel(S.plan.pokal[0][0])} gespielt.</p>`}</div>`;};
V.transfer=()=>{const t=myT(),XI=new Set();S.teams.forEach(x=>bestXI(x.id,x.form).forEach(id=>XI.add(id)));
  let L=S.pl.filter(p=>p.team!==S.my&&p.team>=-1);
  if(TF.pos)L=L.filter(p=>p.pos===TF.pos);if(TF.lg==='f')L=L.filter(p=>p.team===-1);else if(TF.lg)L=L.filter(p=>p.team>=0&&S.teams[p.team].lg===+TF.lg);
  if(TF.list)L=L.filter(p=>p.list||p.team===-1);
  if(TF.q){const q=TF.q.toLowerCase();L=L.filter(p=>p.n.toLowerCase().includes(q)||(p.team>=0&&S.teams[p.team].name.toLowerCase().includes(q)));}
  if(TF.max)L=L.filter(p=>askPrice(p,XI)<=TF.max*1e6);
  L.sort((a,b)=>b.str-a.str);const n=L.length,lim=RU.transferTreffer;L=L.slice(0,lim);
  const mine=squad(S.my).filter(p=>p.list);
  return`<div class="card"><h2>Transfermarkt</h2><p class="dim">Kontostand ${fmt(t.cash)} · Kader ${squad(S.my).length}/${RM.kaderMax} · Jeder Spieler ist anfragbar. Spieler auf der Transferliste sind günstiger, Stammspieler teurer.</p>
  <div class="row" style="margin-bottom:10px">
  <label>Position <select id="tf_pos" onchange="TF.pos=this.value;render()"><option value="">alle</option>${['TW','AB','MF','ST'].map(x=>`<option ${TF.pos===x?'selected':''}>${x}</option>`).join('')}</select></label>
  <label>Liga <select id="tf_lg" onchange="TF.lg=this.value;render()"><option value="">alle</option><option value="1" ${TF.lg==='1'?'selected':''}>1. Liga</option><option value="2" ${TF.lg==='2'?'selected':''}>2. Liga</option><option value="3" ${TF.lg==='3'?'selected':''}>3. Liga</option><option value="f" ${TF.lg==='f'?'selected':''}>vereinslos</option></select></label>
  <label>Max. Ablöse <select id="tf_max" onchange="TF.max=+this.value||'';render()"><option value="">egal</option>${[1,2,5,10,20,40].map(v=>`<option value="${v}" ${TF.max===v?'selected':''}>${v} Mio €</option>`).join('')}</select></label>
  <label>Name / Verein <input id="tf_q" value="${esc(TF.q)}" onchange="TF.q=this.value;render()" placeholder="Enter zum Suchen"></label>
  <label style="grid-auto-flow:column;align-items:center;gap:6px"><input id="tf_list" type="checkbox" ${TF.list?'checked':''} onchange="TF.list=this.checked?1:0;render()"> nur Transferliste &amp; vereinslos</label></div>
  <div class="tw"><table><thead><tr><th>Pos</th><th>Name</th><th class="num">Alter</th><th class="num">Stärke</th><th>Verein</th><th class="num">Marktwert</th><th class="num">Ablöse ca.</th></tr></thead><tbody>
  ${L.map(p=>`<tr class="click" onclick="openP(${p.id})"><td><span class="pos ${p.pos}">${p.pos}</span></td><td>${esc(p.n)}${p.list?' <span class="tag offer">Liste</span>':''}</td><td class="num">${p.age}</td><td class="num str">${Math.round(p.str)}</td><td>${p.team>=0?esc(S.teams[p.team].name):'<span class="dim">vereinslos</span>'}</td><td class="num">${fmt(value(p))}</td><td class="num">${p.team>=0?fmt(askPrice(p,XI)):'ablösefrei'}</td></tr>`).join('')}</tbody></table></div>
  <p class="dim">${n>lim?`${lim} von ${n} Treffern (stärkste zuerst) – Filter nutzen.`:`${n} Treffer.`}</p></div>
  ${mine.length?`<div class="card" style="margin-top:14px"><h3>Deine Transferliste</h3>${mine.map(p=>`<p><a href="#" onclick="openP(${p.id});return false" style="color:var(--chalk)">${esc(p.n)}</a> – Forderung ${fmt(p.ask)} (Marktwert ${fmt(value(p))})</p>`).join('')}</div>`:''}`;};
V.finanzen=()=>{const t=myT(),ent=Object.entries(S.fin),inc=ent.filter(e=>e[1]>0).sort((a,b)=>b[1]-a[1]),ex=ent.filter(e=>e[1]<0).sort((a,b)=>a[1]-b[1]),sum=ent.reduce((s,e)=>s+e[1],0),pay=squad(S.my).reduce((s,p)=>s+p.sal,0),maxL=kreditRahmen(t),P=RF.ticketPreis;
  return`<div class="grid"><div class="card"><h2>Saisonbilanz ${S.season}/${(S.season+1)%100}</h2><table><tbody>${inc.map(([k,v])=>`<tr><td>${k}</td><td class="num posv">${fmt(v)}</td></tr>`).join('')}${ex.map(([k,v])=>`<tr><td>${k}</td><td class="num neg">${fmt(v)}</td></tr>`).join('')}<tr><td><b>Saldo</b></td><td class="num"><b class="${sum<0?'neg':'posv'}">${fmt(sum)}</b></td></tr></tbody></table>${ent.length?'':'<p class="dim">Noch keine Buchungen in dieser Saison.</p>'}</div>
  <div class="card"><h3>Konto & Kredit</h3><div class="facts">${fact('Kontostand',`<span class="${t.cash<0?'neg':''}">${fmt(t.cash)}</span>`)}${fact('Kredit',fmt(S.loan))}${fact('Kreditrahmen',fmt(maxL))}${fact('Gehälter/Saison',fmt(pay))}</div>
  <div class="rgs" style="margin-top:10px">${rgAnzeige({label:'Kredit',sub:'Rahmen '+fmt(maxL),min:0,max:+(maxL/1e6).toFixed(1),wert:S.loan/1e6,einheit:' Mio €',dez:1,art:S.loan>0?'warn':''})}</div>
  <p class="dim" style="margin-top:8px">${de(RF.kreditZins*100)} % Zinsen pro Saison, je Ligaspieltag abgebucht.</p><div class="row"><button onclick="loan(1)">+1 Mio leihen</button><button onclick="loan(5)">+5 Mio leihen</button><button onclick="loan(-1)">1 Mio tilgen</button><button onclick="loan(-99)">Alles tilgen</button></div></div>
  <div class="card"><h3>Eintrittspreis</h3><div class="rgs">${rgFader({id:'price',label:'Ticketpreis',sub:'Ø pro Platz',min:P.min,max:P.max,wert:t.price,einheit:' €',oninput:'preisVorschau(this.value)',onchange:'setPrice(this.value)'})}</div>
  <div id="preisVorschau" class="rgs" style="margin-top:10px">${preisVorschauHTML(t,t.price)}</div>
  <p class="dim" style="margin-top:8px">Richtwert für deinen Verein: etwa ${Math.round(richtPreis(t))} €. Teurere Tickets bringen mehr pro Fan, aber weniger Zuschauer. Die Spanne reicht vom schwächsten bis zum stärksten Gegner der Liga. Pfeiltasten verstellen den Regler in 1-€-Schritten.</p><p>Zuschauerschnitt bisher: <b>${avgAtt()}</b> bei ${t.cap.toLocaleString('de-DE')} Plätzen</p></div>
  <div class="card"><h3>Sponsor & TV</h3>${S.spons?`<p><b>${esc(S.spons.name)}</b>: ${fmt(S.spons.base)} pro Spieltag${S.spons.win?` + ${fmt(S.spons.win)} pro Sieg`:''}, Laufzeit noch ${S.spons.yrs} Saison(s).</p>`:'<p>Noch kein Sponsor gewählt (siehe Büro).</p>'}<p class="dim">TV-Gelder pro Spieltag: ${fmt(tvGeld(t))}</p></div></div>`;};
// Ticketpreis-Vorhersage (Stell-Regler mit Spanne): ändert sich live beim Ziehen, gespeichert wird erst beim Loslassen
function preisVorschauHTML(t,preis){const[lo,hi]=zuschauerSpanne(t,preis),voll=lo>=t.cap*RU.ausverkauftAb,teil=hi>=t.cap*RU.ausverkauftAb;
  return rgUnscharf({label:'Zuschauer',sub:'je Ligaheimspiel, geschätzt',min:0,max:t.cap,spanne:[lo,hi],einheit:' Tsd',f:v=>de(v/1000,1)})+
    rgUrteil(voll?'good':teil?'good':'warn',voll?'Ausverkauft':teil?'Gegen starke Gegner ausverkauft':'Plätze bleiben frei',`Ticketeinnahmen je Heimspiel etwa ${fmt(lo*preis)} bis ${fmt(hi*preis)}. ${voll?'Ein höherer Preis kostet hier kaum Zuschauer.':'Ein niedrigerer Preis bringt mehr Zuschauer, aber weniger pro Kopf.'}`);}
function preisVorschau(v){const P=RF.ticketPreis,p=clamp(Math.round(+v||P.standard),P.min,P.max),o=document.getElementById('priceOut'),b=document.getElementById('preisVorschau');if(o)o.innerHTML=`${p}<small> €</small>`;if(b)b.innerHTML=preisVorschauHTML(myT(),p);}
V.stadion=()=>{const t=myT(),c=S.constr,T=RB.tribuene,L=RB.logen,F=RB.fanshop,schnitt=S.att[1]?S.att[0]/S.att[1]:0;
  return`<div class="grid"><div class="card"><h2>Stadion</h2><div class="facts">${fact('Plätze',t.cap.toLocaleString('de-DE'))}${fact('Zuschauerschnitt',avgAtt())}${fact('VIP-Logen',t.logen)}${fact('Fanshop','Stufe '+t.shop)}</div>
  <div class="rgs" style="margin-top:12px">${rgAnzeige({label:'Zuschauerschnitt',sub:`${t.cap.toLocaleString('de-DE')} Plätze`,min:0,max:t.cap,wert:Math.round(schnitt),zonen:[{von:t.cap*RU.ausverkauftAb,bis:t.cap,art:'good',text:'im Schnitt fast ausverkauft'}]})}
  ${rgAnzeige({label:'Plätze',sub:'Ausbau bis '+T.max.toLocaleString('de-DE'),min:0,max:T.max,wert:t.cap})}${rgAnzeige({label:'VIP-Logen',min:0,max:L.max,wert:t.logen})}${rgAnzeige({label:'Fanshop',sub:'Stufe',min:0,max:F.max,wert:t.shop})}</div></div>
  <div class="card"><h3>Ausbau</h3>${c?`<p>Im Bau: <b>${esc(c.label)}</b>, fertig am ${datumMittel(c.bis)} (in ${c.bis-S.tag} Tagen).</p>`:`<div class="opts">
  <button class="opt" onclick="startBuild('cap')" ${t.cap>=T.max?'disabled':''}><b>Tribüne ausbauen</b><span>+${T.plaetze.toLocaleString('de-DE')} Plätze · ${fmt(T.kosten)} · ${T.wochen} Wochen Bauzeit</span></button>
  <button class="opt" onclick="startBuild('logen')" ${t.logen>=L.max?'disabled':''}><b>${L.anzahl} VIP-Logen</b><span>${fmt(L.kosten)} · ${L.wochen} Wochen · bringen je ${fmt(RF.loge)} pro Heimspiel</span></button>
  <button class="opt" onclick="startBuild('shop')" ${t.shop>=F.max?'disabled':''}><b>Fanshop ${t.shop>=F.max?'(voll ausgebaut)':'Stufe '+(t.shop+1)}</b><span>${t.shop<F.max?fmt(F.kosten[t.shop])+` · ${F.wochen} Wochen · mehr Umsatz pro Zuschauer`:'–'}</span></button></div>`}
  <p class="dim" style="margin-top:8px">Mehr Plätze lohnen sich nur, wenn das Stadion regelmäßig ausverkauft ist.</p></div></div>`;};
// Testspiele (K11 §4.1): anfragen mit Tag und Gegner, Antwort nach 1–3 Tagen, gespielt wird ohne Halt
function testspielKarte(){if(S.phase!=='play')return'';const tage=testspielTage(),l=(S.testspiele||[]).slice().sort((a,b)=>a.tag-b.tag),d0=tage[0];
  const gegner=d0!=null?testspielGegner(d0):[],st={angefragt:'angefragt',zugesagt:'zugesagt',abgesagt:'abgesagt',gespielt:'gespielt'};
  const opt=g=>{const p=d0!=null?zusageChance(g.id,d0):0;return`<option value="${g.id}">${esc(tn(g.id))}${g.am?' (Amateure, auswärts)':` (${g.d>0?'+':''}${g.d.toFixed(1)} Stärke, Heimspiel)`} · Zusage etwa ${Math.round(p*100)} %</option>`;};
  return`<div class="card"><h2>Testspiele</h2>${l.length?`<table><tbody>${l.map(x=>`<tr><td>${datumKurz(x.tag)}</td><td>${x.heim?'gegen':'bei'} ${esc(tn(x.gegner))}</td><td>${x.erg?`<b>${x.erg.hg}:${x.erg.ag}</b>${x.erg.geld?' · '+fmt(x.erg.geld):''}`:st[x.stand]}</td></tr>`).join('')}</tbody></table>`:'<p class="dim">Noch keine Testspiele.</p>'}
    ${tage.length?`<div class="row" style="margin-top:8px;flex-wrap:wrap;gap:6px"><select id="ts_tag">${tage.map(d=>`<option value="${d}">${datumKurz(d)}</option>`).join('')}</select><select id="ts_geg" style="max-width:100%">${gegner.map(opt).join('')}</select><button onclick="tsAnfragen()">Anfragen</button></div>`:'<p class="dim">In den nächsten Wochen ist kein Tag frei (Abstand zu Pflichtspielen, höchstens zwei pro Woche).</p>'}
    <p class="dim" style="margin-top:8px">Testspiele laufen ohne Halt: bis zu ${RTS.wechsel} Wechsel, keine Sperren, weniger Belastung (×${String(RTS.frische).replace('.',',')}), ${Math.round(RTS.praxis*100)} % der Spielpraxis. Profis sagen in der Vorbereitung erst ab der ${RTS.abWoche}. Woche zu, davor nur Amateure. Das Zuschauerinteresse lässt Woche für Woche nach. Die Zusage ist eine Schätzung für den ersten freien Tag.</p></div>`;}
// Trainingslager (K11 §4.2): Ort, Beginn, Dauer, Kosten
function lagerKarte(){if(S.phase!=='play')return'';const akt=(S.lager||[]).filter(l=>l.saison===S.season),tage=[];for(let d=S.tag+1;d<=Math.min(S.plan.ende,S.tag+60);d++)if(lagerSaison(d))tage.push(d);
  const orte=Object.keys(RLA.orte);
  return`<div class="card"><h2>Trainingslager</h2>${akt.map(l=>`<p><b>${esc(RLA.orte[l.ort].name)}</b>, ${datumKurz(l.von)} bis ${datumKurz(l.bis)} (${fmt(l.kosten)})${lagerAktiv(S.tag)===l?' · <span class="tag offer">läuft</span>':''}</p>`).join('')}
    ${tage.length?`<div class="row" style="flex-wrap:wrap;gap:6px"><select id="la_ort" style="max-width:100%">${orte.map(o=>`<option value="${o}">${esc(RLA.orte[o].name)} (${RLA.orte[o].saison==='beide'?'Sommer und Winter':RLA.orte[o].saison==='sommer'?'Sommer':'Winter'}, ${fmt(lagerKosten(o,1))}/Tag)</option>`).join('')}</select><select id="la_von">${tage.map(d=>`<option value="${d}">ab ${datumKurz(d)}</option>`).join('')}</select><select id="la_tage">${[5,6,7,8,9,10].map(n=>`<option value="${n}" ${n===7?'selected':''}>${n} Tage</option>`).join('')}</select><button onclick="lagerBuchen()">Buchen</button></div>`:'<p class="dim">Ein Lager geht in der Vorbereitung oder in der Winterpause.</p>'}
    <p class="dim" style="margin-top:8px">Im Lager wirkt das Training ×${String(RLA.training).replace('.',',')}, die Vertrautheit ×${String(RLA.vertrautheit).replace('.',',')}, bis zum ${RLA.zusammenhaltBis}. Tag wächst der Zusammenhalt. Ab dem ${RLA.kollerAb}. Tag droht Lagerkoller. ${Object.values(RLA.orte).map(o=>`${o.name}: ${o.text}`).join('. ')}.</p></div>`;}
V.training=()=>{const t=myT(),tal=squad(S.my).filter(p=>p.age<=21).sort((a,b)=>b.pot-a.pot),akt=t.vorlage&&RT.vorlagen[t.vorlage]?t.vorlage:'auto';
  // Vorschau: die nächsten sieben Tage mit Einheit nach Abstand zum Spiel (K07 §3.2)
  const tage=[];for(let d=S.tag;d<S.tag+7&&d<=S.plan.ende;d++){const a=spielAbstand(d).get(S.my)||{},e=imUrlaub()&&d<auftaktTag(myT())?null:einheitVerein(t,a,d);
    tage.push(`<tr><td>${esc(datumKurz(d))}</td><td>${a.heute?'<b>Spiel</b>':d<auftaktTag(myT())?'Urlaub':e?`${EINHEIT_NAME[e[0]]}${e[0]!=='frei'?' · '+INTENSITAET_NAME[e[1]]:''}`:'–'}</td></tr>`);}
  const heute=(RT.vorlagen[vorlageVon(t,spielAbstand(S.tag).get(S.my)||{},S.tag)]||{}).name;
  const sq=squad(S.my),belastet=sq.filter(p=>p.inj<=0&&lastQuote(p)>RT.verletzung.sprungAb).sort((a,b)=>lastQuote(b)-lastQuote(a)),einzel=sq.filter(p=>p.ls||p.um);
  return`<div class="grid"><div class="card"><h2>Trainingsplan</h2><div class="opts">${['auto',...Object.keys(RT.vorlagen)].map(k=>`<button class="opt ${akt===k?'on':''}" onclick="setVorlage('${k}')"><b>${k==='auto'?'Co-Trainer entscheidet':RT.vorlagen[k].name}</b><span>${VORLAGE_TEXT[k]}</span></button>`).join('')}</div>
    <h3 style="margin-top:12px">Die nächsten Tage</h3><p class="dim">${akt==='auto'?`Der Co-Trainer plant gerade nach der Vorlage „${esc(heute)}“.`:`Vorlage: ${esc(heute)}.`}</p><table><tbody>${tage.join('')}</tbody></table>
    <p class="dim" style="margin-top:8px">Der Plan richtet sich nach dem Abstand zum Spiel, nicht nach dem Wochentag. Startspieler regenerieren am Tag nach dem Spiel, die übrigen bekommen ein Trainingsspiel für die Spielpraxis.</p></div>
  <div class="card"><h2>Belastung</h2>${belastet.length?`<p>Belastungssprung (akute Last deutlich über der gewohnten, erhöhtes Verletzungsrisiko):</p><table><tbody>${belastet.slice(0,10).map(p=>`<tr class="click" onclick="openP(${p.id})"><td>${esc(p.n)}</td><td class="num">${lastQuote(p).toFixed(2)}</td><td class="num">${Math.round(p.fit)} %</td></tr>`).join('')}</tbody></table>`:'<p class="dim">Niemand mit Belastungssprung. Gefährlich wird es ab etwa 1,3, deutlich ab 1,5.</p>'}
    <h3 style="margin-top:12px">Einzeltraining</h3><p class="dim">${einzel.length} von ${lernPlaetze(S.my)} Plätzen belegt (Lernziele und Umschulungen). Ändern in der Spielerkarte.</p>${einzel.length?`<table><tbody>${einzel.map(p=>`<tr class="click" onclick="openP(${p.id})"><td>${esc(p.n)}</td><td>${p.ls?`lernt ${esc(RP.merkmale[p.ls.k].name)} (${Math.round(p.ls.f)} %)`:''}${p.um?`${p.ls?' · ':''}Umschulung ${esc(p.um)} (${Math.round((p.eig&&p.eig[p.um])||eignung(Object.assign({},p,{eig:null}),p.um)*100)} %)`:''}</td></tr>`).join('')}</tbody></table>`:''}</div>
  ${sommerKarte()}${testspielKarte()}${lagerKarte()}
  <div class="card"><h2>Jugendarbeit</h2><p>Jedes Jahr rücken ${RS.nachwuchs.anzahl} Talente auf. Mehr Investition bringt bessere Talente.</p><div class="opts">${[1,2,3,4,5].map(l=>`<button class="opt ${t.youth===l?'on':''}" onclick="myT().youth=${l};save();render()"><b>Stufe ${l}</b><span>${fmt(RF.jugendKosten[l])} pro Spieltag</span></button>`).join('')}</div></div>
  <div class="card"><h3>Talente bis 21 Jahre</h3>${tal.length?`<table><tbody>${tal.map(p=>`<tr class="click" onclick="openP(${p.id})"><td><span class="pos ${p.pos}">${p.pos}</span></td><td>${esc(p.n)}</td><td class="num">${p.age}</td><td class="num str">${Math.round(p.str)}</td><td>${stars(p)}</td></tr>`).join('')}</tbody></table>`:'<p class="dim">Keine Spieler bis 21 Jahre.</p>'}</div></div>`;};
// Trainerstab (K16): eigene Mitarbeiter, vereinslose zum Einstellen, Wirkung der Rollen
V.stab=()=>{if(!S.stab)return'<div class="card"><p>Dieser Spielstand hat noch keinen Trainerstab.</p></div>';const t=myT(),eig=S.stab.filter(x=>x.team===S.my),rollen=STAB_ROLLEN(),ord=x=>rollen.indexOf(x.r)*100-x.q;
  const fehlt=rollen.filter(r=>!eig.some(x=>x.r===r)),frei=S.stab.filter(x=>x.team<0).sort((a,b)=>ord(a)-ord(b));
  const zeile=x=>`<tr><td>${esc(RST.rollen[x.r].name)}</td><td>${esc(x.n)}</td><td class="num">${stabQText(x)}</td><td class="num">${fmt(x.sal)}</td><td class="num">${x.ct} J.</td><td>${x.ct<=1?`<button onclick="stabVerlaengern(${x.id})">Verlängern</button> `:''}<button onclick="stabEntlassen(${x.id})">Entlassen</button></td></tr>`;
  const zeileFrei=x=>{const voll=stabVon(S.my,x.r).length>=RST.rollen[x.r].plaetze;return`<tr><td>${esc(RST.rollen[x.r].name)}</td><td>${esc(x.n)}, ${x.age}</td><td class="num">${stabQText(x)}</td><td class="num">${fmt(stabGehalt(x.r,x.q,t.lg))}</td><td><button onclick="stabEinstellen(${x.id})" ${voll?'disabled title="alle Plätze dieser Rolle besetzt"':''}>Einstellen</button></td></tr>`;};
  return`<div class="grid wide"><div class="stapel"><div class="card"><h2>Dein Trainerstab</h2><div class="tw"><table><thead><tr><th>Rolle</th><th>Name</th><th class="num">Qualität</th><th class="num">Gehalt/Jahr</th><th class="num">Vertrag</th><th></th></tr></thead><tbody>${eig.sort((a,b)=>ord(a)-ord(b)).map(zeile).join('')}</tbody></table></div>
    ${fehlt.length?`<p class="dim">Nicht besetzt (wirkt wie Qualität ${RST.ohne}): ${fehlt.map(r=>esc(RST.rollen[r].name)).join(', ')}.</p>`:''}
    <p class="dim">Einzeltrainingsplätze: ${stabPlaetze(S.my)}. Die Qualität eigener Mitarbeiter kennst du nach ${RST.genauNachWochen} Wochen genau, sonst als Spanne. Gehälter: ${fmt(stabGehaelter(S.my))} pro Jahr, anteilig je Ligaspiel.</p></div>
  <div class="card"><h2>Vereinslose Mitarbeiter</h2><div class="tw"><table><thead><tr><th>Rolle</th><th>Name</th><th class="num">Qualität</th><th class="num">Gehalt/Jahr</th><th></th></tr></thead><tbody>${frei.map(zeileFrei).join('')}</tbody></table></div></div></div>
  <div class="card"><h2>Was die Rollen bewirken</h2>${rollen.map(r=>`<p><b>${esc(RST.rollen[r].name)}</b> <span class="dim">(${RST.rollen[r].plaetze} ${RST.rollen[r].plaetze>1?'Plätze':'Platz'}${RST.rollen[r].pflicht?', Pflicht':''})</span>: ${esc(RST.rollen[r].text)}</p>`).join('')}</div></div>`;};
// Kabine (K14, K15): Mannschaftsstimmung, Zusammenhalt, Glaubwürdigkeit, Kapitän, Ansprache, Teamevent, Spieler mit Rolle und Stimmung, Zusagen, Beziehungen
V.kabine=()=>{const t=myT(),sq=squad(S.my).sort((a,b)=>stimmung(a)-stimmung(b)),kap=PIX.get(t.kap),tev=teameventMoeglich(),vs=(S.vs||[]).filter(v=>{const p=PIX.get(v.pid);return p&&(v.stand==='offen'||v.ende>absTag(S.tag)-28);}),
    gr=grueppchen(S.my),bz=(S.bz||[]).filter(b=>{const p=PIX.get(b[0]);return p&&p.team===S.my;}),ans=anspracheDieseWoche(),zh=zusammenhalt(t),W=RKA.zusammenhalt.wirkung;
  return`<div class="grid"><div class="card"><h2>Kabine</h2><div class="rgs">${rgAnzeige({label:'Mannschaftsstimmung',sub:'Schnitt, Führungsspieler doppelt, Kapitän zweieinhalbfach',min:0,max:100,wert:Math.round(mannschaftsStimmung(S.my)),zonen:RU.zonenStimmung})}
    ${rgAnzeige({label:'Zusammenhalt',sub:`Teamstärke im Spiel ${de((W[0]+W[1]*zh-1)*100,1)} %`,min:0,max:100,wert:Math.round(zh),zonen:RU.zonenZusammenhalt,marker:[{v:50,t:'Mitte'}]})}
    ${rgAnzeige({label:'Glaubwürdigkeit',sub:'wie sehr die Mannschaft deinen Worten glaubt',min:0,max:100,wert:Math.round(glaub()),zonen:RU.zonenGlaub})}</div>
    <label>Kapitän <select id="kapsel" onchange="setKapitaen(this.value)">${squad(S.my).sort((a,b)=>(b.ch?b.ch.fue:10)-(a.ch?a.ch.fue:10)).map(p=>`<option value="${p.id}" ${p.id===t.kap?'selected':''}>${esc(p.n)}${hatEig(p,'fuehrungsspieler')&&bekannteEigenschaften(p).includes('fuehrungsspieler')?' (Führungsspieler)':''}</option>`).join('')}</select></label>
    <p class="dim">${kap?`${t.kapAuto?'Vom Co-Trainer bestimmt. ':''}Absetzen kostet Stimmung beim Kapitän und seinen Freunden.`:''} Gespräche diese Woche: ${gespraecheDieseWoche()} von ${RGS.proWoche}.</p></div>
    <div class="card"><h3>Mannschaftsansprache</h3><div class="opts">${Object.entries(M_ANSPRACHEN).map(([k,l])=>`<button class="opt" onclick="mansAnsprache('${k}')" ${ans?'disabled':''}><b>${l}${anspracheGeeignet(k)?' ✓':''}</b><span>${esc(M_ANSPRACHE_HILFE[k])}</span></button>`).join('')}</div>
      <p class="dim">${ans?'Diese Woche hast du schon zur Mannschaft gesprochen.':'Höchstens einmal pro Woche. ✓ = passt zur Lage, sonst wirkt sie halb umgekehrt.'}</p>
      <button onclick="teameventUI()">Teamevent (${fmt(tev.kosten)}${tev.abn<1?', wirkt schwächer':''})</button><p class="dim">Ein Tag zusammen: Stimmung und Zusammenhalt +5, nutzt sich innerhalb von vier Wochen ab.</p></div>
    ${gespraechswunschKarte()}
    <div class="card"><h3>Spieler</h3><div class="tw"><table><thead><tr><th>Name</th><th>Rolle</th><th>sieht sich als</th><th class="num">Einsatz</th><th>Stimmung</th><th>Wechselwunsch</th><th>Grund</th></tr></thead><tbody>
    ${sq.map(p=>{const g=hauptgrund(p),e=erwartungEinsatz(p);return`<tr class="click" onclick="openP(${p.id})"><td><span class="pos ${p.pos}">${p.pos}</span> ${esc(p.n)}${p.id===t.kap?' (K)':''}</td><td>${esc(KR_NAME[kaderRolle(p)])}${p.kr?'':' <span class="dim">(Co)</span>'}</td><td>${esc(KR_NAME[KR_AUS_STUFE[einschaetzung(p)]])}</td><td class="num">${Math.round((p.ea==null?e:p.ea)*100)} / ${Math.round(e*100)} %</td><td>${rgMini(Math.round(stimmung(p)),0,100,stimmungArt(p))}</td><td>${p.ww?esc(WW_NAME[p.ww]):''}</td><td>${g?esc(BAUSTEIN_GRUND[g]):''}</td></tr>`;}).join('')}</tbody></table></div>
    <p class="dim">Einsatz: Anteil der Minuten der letzten Wochen gegen seine Erwartung. Klick auf einen Spieler: Gründe, Rolle und Gespräch.</p></div>
    <div class="card"><h3>Zusagen</h3>${vs.length?vs.map(v=>{const p=PIX.get(v.pid);return`<p>${esc(p.n)}: ${esc(versprechenText(v))} <span class="tag ${v.stand==='gebrochen'?'bad':v.stand==='gehalten'?'good':v.stand==='offen'?'':'warn'}">${VERSPRECHEN_STAND[v.stand]}</span></p>`;}).join(''):'<p class="dim">Keine offenen Zusagen.</p>'}<p class="dim">Ab ${RGS.glaubwuerdigkeit.offenAb} offenen Zusagen sinkt die Glaubwürdigkeit jede Woche.</p></div>
    <div class="card"><h3>Beziehungen</h3>${bz.length?`<p><b>Freundschaften:</b> ${bz.filter(b=>b[2]==='F').map(b=>`${esc(last(PIX.get(b[0]).n))} und ${esc(last(PIX.get(b[1]).n))}`).join(', ')||'keine'}</p><p><b>Rivalitäten:</b> ${bz.filter(b=>b[2]==='R').map(b=>`${esc(last(PIX.get(b[0]).n))} und ${esc(last(PIX.get(b[1]).n))}`).join(', ')||'keine'}</p>`:'<p class="dim">Noch keine engen Beziehungen.</p>'}
      ${gr.length?`<p class="bad"><b>Grüppchen:</b> ${gr.map(l=>l.map(p=>esc(last(p.n))).join(', ')).join(' / ')} (kostet Zusammenhalt)</p>`:''}<p class="dim">Freunde leiden beim Abschied des anderen, Rivalen lernen schneller, Grüppchen mit schlechter Stimmung schaden dem Zusammenhalt.</p></div></div>`;};
